candidate_answer_raw:
\begin{aligned}
|T_{>300}|
&=\sum_{\substack{0\le y_1<y_2\le 25\\0\le x_1< x_2\le 25}}
\binom{\gcd(x_2-x_1,\;y_2-y_1)}{1}\cdot (25-\Delta y)\cdot(25-\Delta x)\ \text{(by Pick/area via } \gcd\text{)}\\
&= 17750
\end{aligned}

